import {providers,emptyState,createEpisode,recommendedProviders,applyAction,demoState,uid} from './care.js';
import {readLocal,saveLocal,saveFile,loadFile,clearFiles} from './store.js';
const $=s=>document.querySelector(s),main=$('#main'),modal=$('#modal');
const glyph={home:'<path d="m3 10 8-7 8 7v10H4V10M8 20v-7h6v7"/>',chat:'<path d="M3 3h16v12H9l-6 5zM7 7h8M7 11h5"/>',file:'<path d="M5 2h8l5 5v13H5zM13 2v6h5M8 12h7M8 16h5"/>',team:'<circle cx="8" cy="7" r="3"/><path d="M2 19v-2a6 6 0 0 1 12 0v2M15 4a3 3 0 0 1 0 6M16 13a5 5 0 0 1 4 5"/>',clock:'<circle cx="11" cy="11" r="9"/><path d="M11 6v5l3 2"/>',pulse:'<path d="M1 11h5l3-7 5 14 3-7h4"/>',plus:'<path d="M11 3v16M3 11h16"/>',arrow:'<path d="M4 11h14m-5-5 5 5-5 5"/>',check:'<path d="m4 11 5 5L19 5"/>',shield:'<path d="m11 2 8 3v6c0 5-8 9-8 9s-8-4-8-9V5zM7 11l3 3 5-6"/>',upload:'<path d="M11 16V3m-4 4 4-4 4 4M3 16v4h16v-4"/>',download:'<path d="M11 3v13m-4-4 4 4 4-4M3 16v4h16v-4"/>',mic:'<rect x="8" y="2" width="6" height="11" rx="3"/><path d="M5 10v1a6 6 0 0 0 12 0v-1M11 17v4M7 21h8"/>',video:'<rect x="2" y="5" width="12" height="12" rx="2"/><path d="m14 9 6-4v12l-6-4"/>',transport:'<path d="M2 7h11v10H2zM13 10h4l4 4v3h-8M7 8v6M4 11h6"/><circle cx="6" cy="18" r="2"/><circle cx="17" cy="18" r="2"/>',calendar:'<rect x="3" y="4" width="16" height="16" rx="2"/><path d="M7 2v5M15 2v5M3 9h16M7 13h2M12 13h2"/>',archive:'<path d="M3 3h16v5H3zM5 8v12h12V8M9 12h4"/>',lab:'<path d="M8 2h6M9 2v7l-6 9c-1 2 1 3 2 3h12c2 0 3-1 2-3l-6-9V2M6 15h10"/>',edit:'<path d="m14 3 5 5M3 19l2-6L16 2l4 4L9 17z"/>'};
const icon=n=>`<span class="ico"><svg viewBox="0 0 22 22" aria-hidden="true">${glyph[n]||glyph.file}</svg></span>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=s=>new Date(s).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
const labels={draft:'Ready to share',awaiting_review:'Awaiting clinician',needs_review:'Review needed',approved:'Plan approved',closure_requested:'Recovery review',resolved:'Archived'};
const pill=(s,t)=>`<span class="pill ${t||(['approved','resolved','completed','confirmed'].includes(s)?'green':['needs_review','awaiting_review','requested','closure_requested'].includes(s)?'amber':'')}" >${esc(labels[s]||s.replaceAll('_',' '))}</span>`;
const initials=n=>String(n||'CT').split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const btn=(label,id,kind='secondary',ico='')=>`<button class="button ${kind}" id="${id}">${ico?icon(ico):''}${label}</button>`;
let state,selected=null,view='overview',mode='demo',user=null,role='patient',staffProvider='general',staffClinic='willow',backendAvailable=false,recording=null,recordTimer;
const current=()=>state?.episodes.find(x=>x.id===selected);
const actor=()=>mode==='backend'&&user?{id:user.id,role:user.role,providerId:user.providerId,clinicId:user.clinicId}:{id:role==='patient'?state.profile.ownerId:'demo-'+role,role,providerId:staffProvider,clinicId:staffClinic};
const effectiveRole=()=>mode==='backend'?user?.role||'patient':role;
const apiBase=new URL('api/',document.baseURI);
async function api(route,body){const r=await fetch(new URL(route,apiBase),{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,credentials:'same-origin',signal:AbortSignal.timeout(10000)});let data;try{data=await r.json();}catch{throw Error('The workspace server is unavailable.');}if(!r.ok)throw Error(data.error||'Request failed.');return data;}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5500);}
function open(title,body,tag='YOUR CARE WORKSPACE'){$('#modalContent').innerHTML=`<div class="modal-header"><div><span class="eyebrow">${tag}</span><h2>${title}</h2></div><button class="icon-button" id="closeModal" aria-label="Close dialog">×</button></div>${body}`;$('#closeModal').onclick=()=>modal.close();modal.showModal();}
modal.addEventListener('close',()=>{if(recording&&recording.state!=='inactive')recording.stop();clearTimeout(recordTimer);});
async function refresh(){state=await api('state');if(!state.episodes.some(e=>e.id===selected))selected=state.episodes[0]?.id||null;}
async function action(type,data={}){const e=current();if(!e)throw Error('Open a care episode first.');if(mode==='backend'){await api(`episodes/${e.id}/action`,{type,data});await refresh();}else{const updated=applyAction(e,{type,data},actor()),next=structuredClone(state);next.episodes=next.episodes.map(x=>x.id===e.id?updated:x);saveLocal(next);state=next;}render();}
function run(fn){return async e=>{try{await fn(e);}catch(err){toast(err.message);}};}
function visibleEpisodes(){const a=actor();return state.episodes.filter(e=>a.role==='patient'||(e.consent&&(a.role==='doctor'?e.doctorId===a.providerId:providers.find(p=>p.id===e.doctorId)?.clinicId===a.clinicId)));}
function navigate(v){view=v;location.hash=v;render();}
function heading(title,sub,button=''){return `<div class="page-heading"><div><span class="eyebrow">CARE THAT STAYS WITH YOU</span><h1>${title}</h1><p class="subtitle">${sub}</p></div>${button}</div>`;}
function panel(title,sub,body,action=''){return `<section class="panel"><div class="panel-head"><div><h3>${title}</h3>${sub?`<p>${sub}</p>`:''}</div>${action}</div><div class="panel-body">${body}</div></section>`;}
function empty(title,copy,button=''){return `<div class="empty">${icon('file')}<h3>${title}</h3><p>${copy}</p>${button}</div>`;}
function renderShell(){
 const r=effectiveRole(),items=r==='patient'?[['overview','home','Overview'],['assistant','chat','Care conversation'],['reports','file','Reports & recordings'],['team','team','Care team'],['timeline','clock','Care timeline'],['lab','pulse','Digital twin lab']]:r==='doctor'?[['review','shield','Review queue'],['timeline','clock','Case timeline'],['reports','file','Patient reports'],['lab','pulse','Digital twin lab']]:[['coordination','calendar','Coordination desk'],['timeline','clock','Request timeline']];
 if(!items.some(i=>i[0]===view))view=items[0][0];
 $('#nav').innerHTML=items.map(([key,ico,text])=>`<button class="nav-item ${view===key?'selected':''}" data-view="${key}">${icon(ico)}${text}${key==='lab'?'<span class="tag">ML</span>':''}</button>`).join('');
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('#pageName').textContent=items.find(i=>i[0]===view)?.[2]||'Overview';
 const episodes=visibleEpisodes();if(!episodes.some(e=>e.id===selected))selected=episodes[0]?.id||null;
 $('#episodeList').innerHTML=episodes.map(e=>`<button class="episode-item ${e.id===selected?'active':''} ${e.status==='resolved'?'archived':''}" data-case="${e.id}"><span class="episode-state"></span><span><strong>${esc(e.title)}</strong><small>${esc(mode==='backend'&&r!=='patient'?e.patientName||'Patient':labels[e.status])}</small></span></button>`).join('')||'<p class="tiny" style="padding:10px 13px">No care episodes yet</p>';
 document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{selected=b.dataset.case;render();});
 $('#profileName').textContent=state.profile.name;$('#profileAvatar').textContent=initials(state.profile.name);$('#accountButton').textContent=initials(state.profile.name);$('#patientID').textContent=state.profile.patientId;
 $('#modeBadge').textContent=mode==='demo'?'Synthetic demo':'Connected workspace';$('#roleLabel').hidden=mode!=='demo';$('#roleSelect').value=role;
 $('#modeNote').innerHTML=mode==='demo'?'DEMO · Fictional clinicians and clinics. No real consultation, booking or ambulance dispatch. Use synthetic information only.':'Prototype backend connected · Provider directory remains fictional. No real healthcare services are connected.';
 $('#storageNote').textContent=mode==='demo'?'Saved on this browser · synthetic demo':'Signed-in workspace · server storage';
 $('#newEpisodeSide').hidden=r!=='patient';
}
function progress(e){const n=e.status==='resolved'?4:e.status==='approved'||e.status==='closure_requested'?3:e.status==='awaiting_review'||e.status==='needs_review'?2:1;return `<div class="progress">${['Your story','Clinician review','Care & follow-up','Recovery archive'].map((t,i)=>`<div class="progress-step ${i+1<n?'done':i+1===n?'current':''}"><span class="step-dot">${i+1<n?'✓':i+1}</span>${t}</div>`).join('')}</div>`;}
function caseSummary(e){return `${panel('Your current concern','Patient-reported · diagnosis not established',`<p class="symptoms">${esc(e.symptoms)}</p><div class="inline-meta"><div><small>STARTED</small>${esc(e.onset)}</div><div><small>WORKSPACE STATUS</small>${pill(e.status)}</div><div><small>EPISODE</small>${esc(e.id.slice(0,8).toUpperCase())}</div></div>`)}${progress(e)}`;}
function providerSummary(e){const p=providers.find(x=>x.id===e.doctorId);return p?`<div class="person"><span class="avatar">${p.initials}</span><div><strong>${p.name}</strong><small>${p.specialty}</small><p>${p.clinic}</p></div></div><div class="mini-divider"></div><p class="status-copy">${e.status==='approved'?'Your recorded plan is approved. New concerns go back for review.':e.status==='resolved'?'This care episode is archived. Your history stays available.':'Your workspace is shared. The assigned clinician needs to review it.'}</p><div class="button-row section-gap">${btn('View care team','teamLink','secondary','team')}</div>`:`${empty('A clinician, when you’re ready','Choose a demo clinician and confirm exactly what you want to share.',btn('Find a clinician','teamLink','primary','team'))}`;}
function planBody(e){return e.plan?`<div class="care-note">${esc(e.plan.instructions)}</div><div class="review-meta"><span>Approved ${time(e.plan.approvedAt)}</span><span>Revision ${e.plan.revision}</span></div><p class="tiny">Follow-up: ${esc(e.plan.followup||'Not specified')}</p><p class="tiny" style="margin-top:6px">Review triggers: ${esc(e.plan.reviewTriggers)}</p>${e.reviewedRevision!==e.revision?'<div class="callout section-gap">New information is awaiting review. This plan is historical and does not approve new actions.</div>':''}`:empty('Your care plan will appear here','The assigned clinician writes and approves the plan after reviewing your history and reports.');}
function overview(){const e=current();if(!e){main.innerHTML=heading('Your care, connected.','One place for your story, your care team and your next step.')+`<div class="welcome"><span class="eyebrow">A NEW THREAD STARTS WITH YOU</span><h1>Tell your story once.<br>Keep your care together.</h1><p>Open a care episode, share it with a clinician, and keep reports, check-ins and care arrangements in one continuous workspace.</p><div class="button-row">${btn('Open a care episode','openNew','primary','plus')}${btn('Create demo profile','createProfile','secondary')}</div><div class="step-list"><div><strong>01 · Share your story</strong><small>Symptoms, context and reports</small></div><div><strong>02 · Get a clinician review</strong><small>A specific, recorded care plan</small></div><div><strong>03 · Stay connected</strong><small>Follow-up through recovery</small></div></div></div>`;$('#openNew').onclick=newEpisode;$('#createProfile').onclick=profileModal;return;}
 const check=e.checkins.at(-1),p=providers.find(x=>x.id===e.doctorId),pending=e.tasks.filter(x=>!['completed','declined','cancelled'].includes(x.status)).length;
 main.innerHTML=heading(`Your care, connected.`,`${esc(e.title)} · A continuous thread from your first update to recovery.`,btn('New concern','openNew','secondary','plus'))+`<div class="care-banner"><div class="banner-left">${icon(e.status==='resolved'?'archive':'shield')}<div><h3>${e.status==='resolved'?'A chapter closed. Your history stays.':e.status==='draft'?'Your story is ready for a clinician.':e.status==='needs_review'?'A new update needs another look.':e.status==='approved'?'Your care plan is ready. Let’s stay connected.':'You’re connected. Review is the next step.'}</h3><p>${e.status==='resolved'?esc(e.recoverySummary):e.status==='draft'?'Choose a clinician and consent to share your workspace.':e.status==='approved'?'Record how you feel and keep your care team up to date.':'Your workspace keeps every update in one place.'}</p></div></div>${btn(e.status==='draft'?'Find a clinician':e.status==='resolved'?'Reopen episode':'View care team','bannerAction','secondary','arrow')}</div><div class="metrics"><div class="metric"><div class="metric-label">Latest temperature${icon('pulse')}</div><div class="metric-value">${check?.temperature??'—'}<small>°C</small></div><div class="metric-note">${check?'Patient-reported · '+time(check.time):'No reading recorded'}</div></div><div class="metric"><div class="metric-label">How you’re feeling${icon('chat')}</div><div class="metric-value" style="font-size:23px;text-transform:capitalize">${check?.feeling||'Not recorded'}</div><div class="metric-note">${check?'Your latest check-in':'Add your first check-in'}</div></div><div class="metric"><div class="metric-label">Reports & recordings${icon('file')}</div><div class="metric-value">${String(e.reports.length).padStart(2,'0')}</div><div class="metric-note">Original files · no automatic diagnosis</div></div><div class="metric"><div class="metric-label">Care arrangements${icon('calendar')}</div><div class="metric-value">${String(pending).padStart(2,'0')}</div><div class="metric-note">Active demo requests</div></div></div><div class="workspace-grid"><div class="stack"><div class="panel">${caseSummary(e)}</div>${panel('Your next check-in','A small update keeps the bigger picture clear.',e.status==='resolved'?'<p class="status-copy">This episode is archived. Open a new concern whenever you need a new thread.</p>':`<div class="next-checkin">${icon('clock')}<div><strong>How are you feeling now?</strong><p>Record symptoms, temperature and any changes.</p></div>${btn('Add check-in','checkin','primary','plus')}</div>`)}${panel('Your clinician’s plan','Specific instructions, reviewed for this episode.',planBody(e))}</div><div class="stack">${panel('Your care team',p?'Fictional provider · demonstration':'A person behind your care',providerSummary(e))}${panel('Care arrangements','Provider confirmation is always explicit.',e.tasks.length?e.tasks.slice(-3).map(t=>`<div class="mini-task">${icon(t.kind==='transport'?'transport':'calendar')}<div><strong>${t.kind==='transport'?'Transport request':t.kind==='test'?'Test arrangement':'Appointment'}</strong><small>${esc(t.preferred||'Schedule not specified')}</small></div>${pill(t.status)}</div>`).join(''):empty('Nothing arranged yet','Your requests and provider responses will appear here.'),btn('Request','requestTask','ghost','plus'))}${panel('Keep your history', 'Recovery closes the episode, not your account.',`<p class="status-copy">Your patient ID stays the same. Reports and care history remain available for your next consultation.</p><div class="button-row section-gap">${btn('Export episode','exportCase','secondary','download')}${e.status==='approved'?btn('Request closure','requestClose','ghost'):''}</div>`)}</div></div>`;
 $('#openNew').onclick=newEpisode;$('#bannerAction').onclick=run(async()=>{if(e.status==='resolved'){await action('reopen');toast('Episode reopened. A new clinician review is required.');}else navigate('team');});$('#teamLink').onclick=()=>navigate('team');if($('#checkin'))$('#checkin').onclick=checkinModal;$('#requestTask').onclick=taskModal;$('#exportCase').onclick=exportCase;if($('#requestClose'))$('#requestClose').onclick=run(async()=>{await action('request_close');toast('Recovery review requested. The clinician must close the episode.');});
}
function assistant(){const e=current();if(!e)return overview();main.innerHTML=heading('One continuous conversation.','Your updates and clinician replies stay with the episode.')+`<div class="workspace-grid"><section class="panel"><div class="panel-head"><div><h3>Care conversation</h3><p>Guided intake and shared messages · no diagnostic AI connected</p></div>${pill(e.status)}</div><div class="messages"><div class="bubble"><small>CARETHREAD · GUIDED WORKSPACE</small>Your current concern is “${esc(e.title)}”. You can describe what changed, add a check-in, or attach a report. Messages stay in this workspace. ${e.consent?'Your assigned clinician can review them.':'Choose a clinician and consent to share before a clinician can review them.'}\n\nThis demonstration does not diagnose symptoms or prescribe treatment.</div>${e.messages.map(m=>`<div class="bubble ${m.role==='patient'?'patient':''}"><small>${m.role==='patient'?'YOU':'ASSIGNED CLINICIAN'} · ${time(m.time)}</small>${esc(m.text)}</div>`).join('')}</div><form class="chat-form" id="chatForm"><textarea name="text" aria-label="Your care update" placeholder="Tell your care team what changed…" maxlength="3000" required ${e.status==='resolved'?'disabled':''}></textarea><button class="button primary" ${e.status==='resolved'?'disabled':''}>Save update ${icon('arrow')}</button></form><div class="chat-tools">${btn('Structured check-in','chatCheckin','secondary','plus')}${btn('Voice note','voiceNote','secondary','mic')}${btn('Video note','videoNote','secondary','video')}</div><div class="privacy-strip">Audio/video are original recordings with your written summary. No automatic transcription or clinical interpretation is claimed. Text messages do not replace a structured worsening-symptom check-in.</div></section><div class="stack">${panel('A useful update includes','Help the clinician understand the change.',`<div class="event"><strong>When it changed</strong><p>What started, and when you first noticed it.</p></div><div class="event"><strong>How you feel now</strong><p>Better, the same, or worse than your last update.</p></div><div class="event"><strong>New reports or symptoms</strong><p>Add original files and flag changes in a structured check-in.</p></div>`)}${panel('Clinician review','Your consent controls workspace access.',providerSummary(e))}</div></div>`;
 $('#chatForm').onsubmit=run(async ev=>{ev.preventDefault();const f=new FormData(ev.target);await action('message',{text:f.get('text')});toast('Update saved. Use a check-in to flag new or worsening symptoms.');});$('#chatCheckin').onclick=checkinModal;$('#voiceNote').onclick=()=>recordModal(false);$('#videoNote').onclick=()=>recordModal(true);$('#teamLink').onclick=()=>navigate('team');}
function reports(){const e=current();if(!e)return overview();main.innerHTML=heading('The evidence behind your story.','Original reports and recordings, together with your own context.',effectiveRole()==='patient'?btn('Add a report','uploadReport','primary','upload'):'')+panel('Reports & recordings','Patient uploads · original values have not been automatically verified.',e.reports.length?e.reports.map(r=>`<div class="report"><div class="file-icon">${r.type.startsWith('audio')?'AUDIO':r.type.startsWith('video')?'VIDEO':r.type==='application/pdf'?'PDF':'FILE'}</div><div><strong>${esc(r.name)}</strong><small>${time(r.time)} · ${(r.size/1024).toFixed(0)} KB · Patient supplied</small><p>${esc(r.summary||'No written context provided.')}</p></div><button class="button secondary" data-file="${r.id}">${icon('download')}Open file</button></div>`).join(''):empty('Your reports, in one place','Add a PDF, photo, text report or a recorded update. Use synthetic information in this demo.'))+`<div class="callout section-gap">A new report returns an approved episode to clinician review. Uploading a file does not establish a diagnosis or make an AI recommendation accurate. Up to 5 MB per file, 12 attachments per episode.</div>`;
 if($('#uploadReport'))$('#uploadReport').onclick=uploadModal;document.querySelectorAll('[data-file]').forEach(b=>b.onclick=run(()=>downloadFile(b.dataset.file)));}
function team(){const e=current();if(!e)return overview();const ordered=recommendedProviders(e.category);main.innerHTML=heading('A care team around you.','Choose a clinician, review what is shared, and keep care arrangements visible.')+`<div class="workspace-grid"><div class="stack">${panel('Find a suitable clinician','Fictional directory · credentials and schedules are demonstration fixtures.',ordered.map((p,i)=>`<div class="provider-card ${p.id===e.doctorId?'matched':''}"><div class="queue-row"><div class="person"><span class="avatar" style="background:${p.color}">${p.initials}</span><div><strong>${p.name}</strong><small>${p.specialty}</small><p>${p.qualification}</p></div></div>${p.id===e.doctorId?pill('Selected','green'):i===0?pill('Category match','blue'):''}</div><div class="provider-info"><span>${p.clinic} · ${p.language}</span><span>Demo availability: ${p.available}</span></div><div class="button-row"><button class="button ${p.id===e.doctorId?'secondary':'primary'}" data-share="${p.id}" ${e.status==='resolved'?'disabled':''}>${p.id===e.doctorId?'Review sharing':'Choose & share'} ${icon('arrow')}</button></div></div>`).join(''))}${panel('Appointments, tests & transport','A request becomes confirmed only after a provider response.',tasksMarkup(e),btn('New request','newTask','secondary','plus'))}</div><div class="stack">${panel('What gets shared','Only after you confirm consent.',`<p class="symptoms">Your symptoms, check-ins, messages and original reports go to the assigned clinician.</p><div class="mini-divider"></div><p class="status-copy">The clinic desk receives coordination details. It does not receive report files or the full symptom history in the connected backend.</p>${e.consent?`<div class="button-row section-gap">${btn('Withdraw sharing','withdraw','danger')}</div>`:''}`)}${panel('Need urgent help?','This prototype cannot provide emergency response.',`<div class="callout">The transport workflow is a simulation. No real ambulance is dispatched. For urgent help, contact your local emergency service or healthcare provider directly.</div>`)}${mode==='demo'?panel('Try the whole care loop','Switch demo roles in the top bar.',`<p class="status-copy">After sharing, switch to Clinician to review and approve a plan. Then switch to Clinic desk to accept and confirm a coordination request. These are local demonstration actions.</p>`):''}</div></div>`;
 document.querySelectorAll('[data-share]').forEach(b=>b.onclick=()=>shareModal(b.dataset.share));$('#newTask').onclick=taskModal;if($('#withdraw'))$('#withdraw').onclick=()=>confirmWithdraw();}
function tasksMarkup(e,desk=false){return e.tasks.length?e.tasks.map(t=>`<div class="task"><div class="task-title"><strong>${t.kind==='transport'?'Ambulance / transport request':t.kind==='test'?'Test arrangement':'Appointment request'}</strong>${pill(t.status)}</div><p>${esc(t.details)}</p><p>Preferred: ${esc(t.preferred||'Not specified')}</p>${t.confirmation?`<div class="task-ref">Provider reference: ${esc(t.confirmation)}</div>`:''}${desk?`<div class="button-row">${t.status==='requested'?`<button class="button secondary" data-task="${t.id}" data-status="accepted">Accept request</button><button class="button ghost" data-task="${t.id}" data-status="declined">Decline</button>`:t.status==='accepted'?`<button class="button primary" data-task="${t.id}" data-status="confirmed">Confirm arrangement</button>`:t.status==='confirmed'?`<button class="button secondary" data-task="${t.id}" data-status="completed">Mark completed</button>`:''}</div>`:''}</div>`).join(''):empty('No requests yet','Appointment requests can be created while a clinician review is pending. Test and transport requests require a current approved plan.');}
function timeline(){const e=current();if(!e)return overview();main.innerHTML=heading('Every update has a place.','A traceable record of your episode, from intake to recovery.',btn('Export episode','timelineExport','secondary','download'))+`<section class="panel"><div class="panel-head"><div><h3>${esc(e.title)}</h3><p>${esc(e.id)} · ${e.events.length} recorded events</p></div>${pill(e.status)}</div><div class="timeline">${[...e.events].reverse().map(x=>`<div class="event"><small>${time(x.time)} · ${esc(x.actor)}</small><strong>${esc(x.title)}</strong><p>${esc(x.detail)}</p></div>`).join('')}</div></section>`;$('#timelineExport').onclick=exportCase;}
function review(){const cases=visibleEpisodes(),e=current();main.innerHTML=heading('A thoughtful review. A clear next step.','Assigned clinician workspace · review the current revision before approving.',mode==='demo'?'<select id="clinicianSelect" aria-label="Demo clinician">'+providers.map(p=>`<option value="${p.id}" ${p.id===staffProvider?'selected':''}>${p.name}</option>`).join('')+'</select>':btn('Refresh queue','refreshQueue','secondary'))+`<div class="queue-grid"><div class="queue-list">${cases.map(c=>`<button class="queue-card ${c.id===selected?'active':''}" data-review-case="${c.id}"><div class="queue-row"><strong>${esc(c.patientName||state.profile.name)}</strong>${pill(c.status)}</div><p>${esc(c.title)}</p><small>Revision ${c.revision} · ${c.reports.length} reports</small></button>`).join('')||empty('No assigned cases','A patient must choose this clinician and consent to share.')}</div><div class="stack">${e?`${panel('Patient-reported history',`${esc(e.patientName||state.profile.name)} · ${esc(e.onset)} · Revision ${e.revision}`,`<p class="symptoms">${esc(e.symptoms)}</p><div class="mini-divider"></div><p class="tiny">Latest check-in: ${e.checkins.at(-1)?esc(e.checkins.at(-1).feeling)+' · '+esc(e.checkins.at(-1).temperature??'No temperature')+' °C':'Not recorded'}</p><p class="status-copy">${esc(e.checkins.at(-1)?.note||'')}</p><div class="button-row section-gap">${btn('Open reports','doctorReports','secondary','file')}${btn('View timeline','doctorTimeline','secondary','clock')}</div>`)}${e.status==='resolved'?panel('Recovery summary','Archived episode · retained history.',`<div class="care-note">${esc(e.recoverySummary)}</div>`):`<section class="panel"><div class="panel-head"><div><h3>${e.closeRequested?'Recovery review requested':'Review & approve a specific plan'}</h3><p>Approval covers this recorded revision only.</p></div></div><form id="approvalForm" class="review-form"><label>Follow-up instructions<textarea name="instructions" minlength="20" maxlength="4000" required placeholder="Write the specific follow-up plan after reviewing this episode…">${esc(e.plan?.instructions||'')}</textarea></label><label>Follow-up timing<input name="followup" maxlength="100" placeholder="Specify when the patient should check in again" value="${esc(e.plan?.followup||'')}"></label><label>When another review is needed<textarea name="reviewTriggers" maxlength="1000" placeholder="Record the changes that require reassessment">${esc(e.plan?.reviewTriggers||'New or worsening symptoms, or a new test report.')}</textarea></label><label class="check-label"><input type="checkbox" name="reviewed" required>I reviewed the patient history, latest updates and original reports. This approval applies to revision ${e.revision} and does not authorize unrelated treatment changes.</label><div class="button-row"><button class="button primary">${icon('check')}Approve recorded plan</button>${e.closeRequested?btn('Close care episode','resolveEpisode','secondary','archive'):''}</div></form><div class="privacy-strip">${mode==='demo'?'Demo clinician role. This is not a real medical approval.':'Staff access requires an operator-issued invitation. Provider details remain demonstration fixtures.'}</div></section>`}${panel('Shared conversation','Messages remain visible in the patient workspace.',`<div class="messages" style="padding:0;min-height:0">${e.messages.map(m=>`<div class="bubble ${m.role==='patient'?'patient':''}"><small>${m.role==='patient'?'PATIENT':'CLINICIAN'} · ${time(m.time)}</small>${esc(m.text)}</div>`).join('')||'<p class="tiny">No shared messages yet.</p>'}</div><form class="chat-form section-gap" id="doctorChat"><textarea name="text" aria-label="Clinician message" maxlength="3000" placeholder="Write a reply to the patient…" required ${e.status==='resolved'?'disabled':''}></textarea><button class="button secondary" ${e.status==='resolved'?'disabled':''}>Send reply</button></form>`)}`:panel('No workspace selected','',empty('The queue is clear','Choose a clinician with an assigned case, or share a patient episode first.'))}</div></div>`;
 if($('#clinicianSelect'))$('#clinicianSelect').onchange=ev=>{staffProvider=ev.target.value;selected=null;render();};if($('#refreshQueue'))$('#refreshQueue').onclick=run(async()=>{await refresh();render();});document.querySelectorAll('[data-review-case]').forEach(b=>b.onclick=()=>{selected=b.dataset.reviewCase;render();});if(!e)return;
 $('#doctorReports').onclick=()=>navigate('reports');$('#doctorTimeline').onclick=()=>navigate('timeline');if($('#approvalForm'))$('#approvalForm').onsubmit=run(async ev=>{ev.preventDefault();const f=new FormData(ev.target);await action('approve',{instructions:f.get('instructions'),followup:f.get('followup'),reviewTriggers:f.get('reviewTriggers'),reviewed:f.get('reviewed')==='on',revision:e.revision});toast('Plan approval recorded for this revision.');});if($('#resolveEpisode'))$('#resolveEpisode').onclick=()=>resolveModal();$('#doctorChat').onsubmit=run(async ev=>{ev.preventDefault();await action('message',{text:new FormData(ev.target).get('text')});toast('Clinician reply saved.');});}
function coordination(){const e=current();main.innerHTML=heading('The next step, made explicit.','Clinic desk · request receipt and confirmation are separate events.',mode==='demo'?`<select id="clinicSelect" aria-label="Demo clinic"><option value="willow" ${staffClinic==='willow'?'selected':''}>Willow Family Clinic</option><option value="northstar" ${staffClinic==='northstar'?'selected':''}>Northstar Medical Centre</option></select>`:btn('Refresh requests','refreshDesk','secondary'))+`<div class="callout" style="margin-bottom:20px">All organisations and responses are fictional in this demonstration. No real appointment, test or ambulance service is connected. In the backend, clinic accounts receive logistics details only.</div>${e?panel('Coordination requests',`${esc(e.patientName||state.profile.name)} · assigned to ${esc(providers.find(p=>p.id===e.doctorId)?.clinic||'clinic')}`,tasksMarkup(e,true)):panel('No requests assigned','',empty('Waiting for a care request','A patient must share with a clinician at this clinic before coordination can begin.'))}`;
 if($('#clinicSelect'))$('#clinicSelect').onchange=ev=>{staffClinic=ev.target.value;selected=null;render();};if($('#refreshDesk'))$('#refreshDesk').onclick=run(async()=>{await refresh();render();});document.querySelectorAll('[data-task]').forEach(b=>b.onclick=run(async()=>{if(b.dataset.status==='confirmed')confirmationModal(b.dataset.task);else{await action('task_status',{id:b.dataset.task,status:b.dataset.status});toast('Provider request status updated.');}}));}
function lab(){main.innerHTML=heading('The patient twin, under the hood.','The original glucose model remains a reproducible, synthetic digital-twin demonstration.')+`<div class="callout" style="margin-bottom:18px">This lab uses its own fictional diabetes patients. Fever episodes are not glucose predictions. The model has no clinical validation and does not prescribe treatment.</div><a class="button secondary" href="glucoahead.html" target="_blank" rel="noopener">Open digital twin lab in a new tab ↗</a><iframe class="embedded-lab section-gap" title="Synthetic glucose digital twin lab" src="glucoahead.html"></iframe>`;}
function render(){if(!state)return;if(mode==="backend"&&!user){welcome();return;}renderShell();if(effectiveRole()==='doctor'&&view==='review')review();else if(effectiveRole()==='clinic'&&view==='coordination')coordination();else if(view==='assistant')assistant();else if(view==='reports')reports();else if(view==='team')team();else if(view==='timeline')timeline();else if(view==='lab')lab();else overview();}
function newEpisode(){open('Start a new care thread',`<p class="modal-subtitle">Describe your concern in your own words. This records symptoms, not a confirmed diagnosis.</p><form id="episodeForm"><label class="field">Concern title<input name="title" placeholder="e.g. Fever & tiredness" maxlength="100" required></label><div class="fields"><label class="field">When did it start?<input name="onset" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label class="field">Care category<select name="category"><option value="general">General symptoms / unsure</option><option value="diabetes">Diabetes follow-up</option><option value="heart">Heart / cardiovascular follow-up</option></select></label><label class="field span2">What is happening?<textarea name="symptoms" placeholder="Symptoms, when they started, and how you feel now…" minlength="8" maxlength="3000" required></textarea></label></div><p class="tiny">${mode==='demo'?'Use fictional information. This demo saves on your device.':'This information is private until you choose a clinician and consent to share.'}</p><div class="form-actions"><button class="button primary">Open workspace ${icon('arrow')}</button></div></form>`);$('#episodeForm').onsubmit=run(async ev=>{ev.preventDefault();const d=Object.fromEntries(new FormData(ev.target));let e;if(mode==='backend'){e=await api('episodes',d);await refresh();}else{e=createEpisode(d,state.profile.ownerId);e.patientName=state.profile.name;const next=structuredClone(state);next.episodes.unshift(e);saveLocal(next);state=next;}selected=e.id;view='overview';modal.close();render();toast('Your care workspace is open. Choose a clinician when ready.');});}
function checkinModal(){if(current()?.status==='resolved')return toast('This episode is archived. Reopen it first.');open('How are you feeling?',`<p class="modal-subtitle">Record your own observations. New or worsening symptoms trigger another clinician review.</p><form id="checkinForm"><fieldset class="field feeling-field"><legend>Compared with your last update</legend><div class="choice-group"><label class="choice"><input type="radio" name="feeling" value="better" required>Better</label><label class="choice"><input type="radio" name="feeling" value="same" checked>The same</label><label class="choice"><input type="radio" name="feeling" value="worse">Worse</label></div></fieldset><label class="field">Temperature, if measured (°C)<input type="number" name="temperature" min="30" max="45" step=".1" placeholder="Optional"></label><label class="field">What changed?<textarea name="note" maxlength="1500" placeholder="Describe your current status…"></textarea></label><label class="check-label"><input type="checkbox" name="newSymptoms">I have a new symptom or a new concern for the clinician.</label><div class="form-actions"><button class="button primary">Save check-in</button></div></form>`);$('#checkinForm').onsubmit=run(async ev=>{ev.preventDefault();const f=new FormData(ev.target);await action('checkin',{feeling:f.get('feeling'),temperature:f.get('temperature'),note:f.get('note'),newSymptoms:f.get('newSymptoms')==='on'});modal.close();toast('Check-in saved in your care timeline.');});}
function shareModal(id){const p=providers.find(p=>p.id===id);open('Choose who sees your story',`<div class="person"><span class="avatar">${p.initials}</span><div><strong>${p.name}</strong><small>${p.specialty} · ${p.clinic}</small></div></div><p class="modal-subtitle section-gap">This fictional clinician will see this episode’s symptoms, check-ins, reports and messages. The clinic desk sees only coordination details in the backend.</p><form id="shareForm"><label class="check-label"><input type="checkbox" name="consent" required>I consent to share this episode with the selected clinician for review. I understand this is a simulated provider in the demonstration.</label><div class="form-actions"><button class="button primary">Share & request review</button></div></form>`);$('#shareForm').onsubmit=run(async ev=>{ev.preventDefault();await action('share',{doctorId:id,consent:true});modal.close();toast('Review requested. No care plan is approved yet.');});}
function confirmWithdraw(){open('Withdraw workspace sharing',`<p class="modal-subtitle">The assigned clinician and clinic will lose access in the connected backend. Pending requests are cancelled. Your own episode history remains available.</p><div class="form-actions">${btn('Withdraw sharing','confirmWithdraw','danger')}</div>`);$('#confirmWithdraw').onclick=run(async()=>{await action('revoke');modal.close();toast('Sharing withdrawn.');});}
function taskModal(){if(!current()?.consent)return toast('Choose a clinician and consent to share first.');open('Arrange the next step',`<p class="modal-subtitle">Provider requests are simulated. A request is not a confirmed booking or ambulance dispatch.</p><form id="taskForm"><label class="field">Request type<select name="kind"><option value="appointment">Clinician appointment</option><option value="test">Test arrangement · approved plan required</option><option value="transport">Ambulance / transport · simulation only</option></select></label><label class="field">Details<textarea name="details" minlength="5" maxlength="1000" placeholder="What needs arranging?" required></textarea></label><label class="field">Preferred date or time<input name="preferred" maxlength="100" placeholder="e.g. Tomorrow afternoon"></label><div class="callout">This prototype cannot arrange emergency care. Contact your local emergency service or healthcare provider directly if you need urgent help.</div><div class="form-actions"><button class="button primary">Send demo request</button></div></form>`);$('#taskForm').onsubmit=run(async ev=>{ev.preventDefault();await action('request_task',Object.fromEntries(new FormData(ev.target)));modal.close();toast('Request saved. Provider acknowledgement is pending.');});}
function confirmationModal(id){open('Confirm the arrangement',`<p class="modal-subtitle">Record a provider confirmation reference. In this demonstration, it is a fictional confirmation and does not book or dispatch a real service.</p><form id="confirmTaskForm"><label class="field">Confirmation / booking reference<input name="confirmation" minlength="5" maxlength="300" placeholder="e.g. DEMO-APT-104 · Tuesday 10:00" required></label><div class="form-actions"><button class="button primary">Record confirmation</button></div></form>`);$('#confirmTaskForm').onsubmit=run(async ev=>{ev.preventDefault();await action('task_status',{id,status:'confirmed',confirmation:new FormData(ev.target).get('confirmation')});modal.close();toast('Demo provider confirmation recorded.');});}
function resolveModal(){open('Close this care episode',`<p class="modal-subtitle">Review the recovery request and add a closing summary. The episode is archived; the patient ID and history remain.</p><form id="resolveForm"><label class="field">Recovery summary<textarea name="summary" minlength="15" maxlength="3000" placeholder="Record the recovery review and closing notes…" required></textarea></label><div class="form-actions"><button class="button primary">Archive care episode</button></div></form>`);$('#resolveForm').onsubmit=run(async ev=>{ev.preventDefault();await action('resolve',{summary:new FormData(ev.target).get('summary')});modal.close();toast('Episode archived. Your care history stays connected.');});}
function download(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportCase(){const e=current();if(!e)return;download(`carethread-${e.id.slice(0,8)}.json`,new Blob([JSON.stringify({disclosure:'Research prototype; provider actions are simulated.',patientId:state.profile.patientId,episode:e},null,2)],{type:'application/json'}));toast('Episode exported. Original attachment files are not embedded.');}
async function downloadFile(id){const r=current().reports.find(r=>r.id===id);if(mode==='backend'){const response=await fetch(new URL('attachments/'+id,apiBase),{credentials:'same-origin'});if(!response.ok)throw Error('Attachment unavailable or access denied.');download(r.name,await response.blob());}else{const blob=await loadFile(id);if(!blob)throw Error('This file is unavailable on this browser.');download(r.name,blob);}}
async function attach(blob,name,summary){if(blob.size>5*1024*1024)throw Error('Choose a file smaller than 5 MB.');if(!blob.size)throw Error('This file is empty.');let id=uid();if(mode==='backend'){const bytes=new Uint8Array(await blob.arrayBuffer());let str='';for(let i=0;i<bytes.length;i+=8192)str+=String.fromCharCode(...bytes.subarray(i,i+8192));const result=await api('attachments',{name,type:blob.type,base64:btoa(str)});id=result.id;}else await saveFile(id,blob);await action('report',{id,name,type:blob.type,size:blob.size,summary});}
function uploadModal(){if(current()?.status==='resolved')return toast('Reopen this episode before adding a report.');open('Add context, keep the original',`<p class="modal-subtitle">PDF, JPEG, PNG or plain text. Max 5 MB. No automatic report extraction or diagnosis.</p><form id="uploadForm"><label class="field">Original report<input type="file" name="file" accept="application/pdf,image/jpeg,image/png,text/plain" required></label><label class="field">Your context<textarea name="summary" maxlength="1500" placeholder="What is this report, and what would you like reviewed?"></textarea></label><div class="form-actions"><button class="button primary">Save report</button></div></form>`);$('#uploadForm').onsubmit=run(async ev=>{ev.preventDefault();const f=new FormData(ev.target),file=f.get('file');if(!['application/pdf','image/jpeg','image/png','text/plain'].includes(file.type))throw Error('Use PDF, JPEG, PNG or plain text.');await attach(file,file.name,f.get('summary'));modal.close();toast('Original report added. Clinician review is required.');});}
function recordModal(video){if(current()?.status==='resolved')return toast('Reopen this episode before recording an update.');open(video?'Add a video update':'Add a voice update',`<p class="modal-subtitle">Record a short original update and add a written summary. No transcription or medical interpretation is performed.</p><div class="recorder"><p id="recordStatus">${video?'Camera + microphone':'Microphone'} access starts only when you choose Record.</p><${video?'video':'audio'} id="recordPreview" controls ${video?'playsinline':''}></${video?'video':'audio'}><div class="button-row section-gap">${btn('Record','startRecording','primary',video?'video':'mic')}${btn('Stop','stopRecording','secondary')}</div></div><label class="field section-gap">Written summary<textarea id="recordSummary" maxlength="1500" placeholder="Summarize the update for your care team…" required></textarea></label><div class="form-actions">${btn('Save recording','saveRecording','primary')}</div>`);let blob=null,stream=null,url=null;$('#stopRecording').disabled=true;$('#saveRecording').disabled=true;
 $('#startRecording').onclick=run(async()=>{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Recording is not supported here. You can attach a written update instead.');stream=await navigator.mediaDevices.getUserMedia({audio:true,video:video?{width:640,height:360}:false});const preferred=video?'video/webm':'audio/webm';recording=new MediaRecorder(stream,MediaRecorder.isTypeSupported(preferred)?{mimeType:preferred,videoBitsPerSecond:300000,audioBitsPerSecond:32000}:undefined);const chunks=[];recording.ondataavailable=ev=>{if(ev.data.size)chunks.push(ev.data);};recording.onstop=()=>{stream.getTracks().forEach(t=>t.stop());blob=new Blob(chunks,{type:recording.mimeType});if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(blob);if(!$('#recordPreview'))return;$('#recordPreview').srcObject=null;$('#recordPreview').src=url;$('#recordPreview').muted=false;$('#recordStatus').textContent='Recording ready. Add a written summary before saving.';$('#recordStatus').classList.remove('recording');$('#startRecording').disabled=false;$('#stopRecording').disabled=true;$('#saveRecording').disabled=false;};recording.start();$('#recordStatus').textContent=`Recording… maximum ${video?'30':'60'} seconds.`;$('#recordStatus').classList.add('recording');$('#startRecording').disabled=true;$('#stopRecording').disabled=false;if(video){$('#recordPreview').srcObject=stream;$('#recordPreview').muted=true;$('#recordPreview').play();}recordTimer=setTimeout(()=>{if(recording.state!=='inactive')recording.stop();},video?30000:60000);});$('#stopRecording').onclick=()=>{clearTimeout(recordTimer);if(recording?.state!=='inactive')recording.stop();};$('#saveRecording').onclick=run(async()=>{const summary=$('#recordSummary').value.trim();if(!summary)throw Error('Add a short written summary.');await attach(blob,`${video?'video':'voice'}-update-${Date.now()}.webm`,summary);modal.close();if(url)URL.revokeObjectURL(url);toast('Original recording saved with your summary.');});}
function profileModal(){if(mode==='backend'){open('Your connected account',`<p class="modal-subtitle">${esc(user.name)} · ${esc(user.role)}<br>${esc(state.profile.patientId)}</p><div class="callout">Provider integrations and medical AI are not connected. This is a research prototype.</div><div class="form-actions">${btn('Sign out','signOut','secondary')}</div>`);$('#signOut').onclick=run(async()=>{await api('auth/logout',{});user=null;modal.close();welcome();});return;}
 open('Your demo profile',`<p class="modal-subtitle">This is a browser-local demo profile, not an authenticated patient account. Use fictional information only.</p><form id="profileForm"><label class="field">Display name<input name="name" value="${esc(state.profile.name)}" minlength="2" maxlength="100" required></label><p class="tiny">Patient ID: ${esc(state.profile.patientId)} · stays across care episodes</p><div class="form-actions"><button class="button primary">Save profile</button></div></form><div class="mini-divider"></div><div class="button-row">${backendAvailable?btn('Sign in to backend','openAuth','secondary'):''}${btn('Reset synthetic demo','resetDemo','danger')}</div>`);$('#profileForm').onsubmit=run(async ev=>{ev.preventDefault();const next=structuredClone(state);next.profile.name=new FormData(ev.target).get('name').trim();saveLocal(next);state=next;modal.close();render();});if($('#openAuth'))$('#openAuth').onclick=()=>{modal.close();authModal();};$('#resetDemo').onclick=()=>{open('Reset this browser’s demo?',`<p class="modal-subtitle">This removes this browser’s saved demo episodes and attachments and restores the fictional sample case.</p><div class="form-actions">${btn('Reset local demo','confirmReset','danger')}</div>`);$('#confirmReset').onclick=run(async()=>{await clearFiles();state=demoState();saveLocal(state);selected=state.episodes[0].id;role='patient';view='overview';modal.close();render();toast('Synthetic sample workspace restored.');});};}
function authModal(register=false){open(register?'Create your patient account':'Welcome back',`<p class="modal-subtitle">Connected backend · passwords are hashed and session cookies are HttpOnly. This prototype is not a clinical service.</p><div class="auth-tabs"><button type="button" id="loginTab" class="${!register?'active':''}">Sign in</button><button type="button" id="registerTab" class="${register?'active':''}">Create account</button></div><form id="authForm">${register?'<label class="field">Your name<input name="name" minlength="2" maxlength="100" autocomplete="name" required></label>':''}<label class="field">Email<input type="email" name="email" autocomplete="email" required></label><label class="field">Password<input type="password" name="password" minlength="12" maxlength="128" autocomplete="${register?'new-password':'current-password'}" required></label>${register?'<label class="field">Staff invitation (optional)<input type="password" name="invite" autocomplete="off" placeholder="Leave blank for a patient account"></label>':''}<p class="tiny">12–128 characters. Staff roles require an operator-issued invitation.</p><p class="form-error" id="authError" role="alert"></p><div class="form-actions"><button class="button primary">${register?'Create account':'Sign in'}</button></div></form>`);$('#loginTab').onclick=()=>{modal.close();authModal(false);};$('#registerTab').onclick=()=>{modal.close();authModal(true);};$('#authForm').onsubmit=async ev=>{ev.preventDefault();const button=ev.target.querySelector('button');button.disabled=true;try{const result=await api('auth/'+(register?'register':'login'),Object.fromEntries(new FormData(ev.target)));user=result.user;mode='backend';await refresh();view=user.role==='doctor'?'review':user.role==='clinic'?'coordination':'overview';modal.close();render();toast('Signed in to your server workspace.');}catch(err){$('#authError').textContent=err.message;button.disabled=false;}};}
function welcome(){state=emptyState('Your account');selected=null;renderShell();main.innerHTML=heading('Care that stays connected.','Your story, a clinician’s review and the next step, in one workspace.')+`<div class="welcome"><span class="eyebrow">FROM FIRST CONCERN TO FOLLOW-UP</span><h1>A little less navigating.<br>A little more care.</h1><p>Create a private workspace, share your episode with an assigned clinician, and keep the care plan, reports and follow-up together.</p><div class="button-row">${btn('Create an account','signup','primary','arrow')}${btn('Sign in','signin','secondary')}${btn('Explore synthetic demo','exploreDemo','ghost')}</div><div class="step-list"><div><strong>Tell your story</strong><small>Text, reports and recorded updates</small></div><div><strong>A clinician reviews</strong><small>Explicit approval for a specific plan</small></div><div><strong>Care stays coordinated</strong><small>Check-ins, requests and recovery</small></div></div></div><div class="callout">Research prototype. Clinician directory is fictional. No medical AI, real hospitals or emergency services are connected.</div>`;$('#signup').onclick=()=>authModal(true);$('#signin').onclick=()=>authModal();$('#exploreDemo').onclick=loadDemo;}
function loadDemo(){mode='demo';user=null;role='patient';state=readLocal()||demoState();if(!state.profile||!Array.isArray(state.episodes))state=demoState();saveLocal(state);selected=state.episodes[0]?.id;view='overview';render();}
$('#newEpisodeSide').onclick=()=>{if(mode==='backend'&&!user)return authModal(true);newEpisode();};$('#profileButton').onclick=()=>{if(mode==='backend'&&!user)return authModal();profileModal();};$('#accountButton').onclick=()=>{if(mode==='backend'&&!user)return authModal();profileModal();};$('#roleSelect').onchange=ev=>{role=ev.target.value;selected=null;view=role==='doctor'?'review':role==='clinic'?'coordination':'overview';render();};
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(v&&v!==view&&state&&(mode==='demo'||user)){view=v;render();}});
async function start(){try{const r=await api('session');backendAvailable=true;mode='backend';user=r.user;if(user){await refresh();view=user.role==='doctor'?'review':user.role==='clinic'?'coordination':'overview';render();}else welcome();}catch{backendAvailable=false;loadDemo();}}
start();
